import{z as c,x as i,o,c as l,q as d,j as r,D as a,d as n,s as E,S as s}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"虚拟文件系统","description":"","frontmatter":{"title":"虚拟文件系统","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vfs.md","filePath":"cs/vfs.md","lastUpdated":1791063341000}'),p={name:"cs/vfs.md"};function A(S,e,B,F,m,_){const t=i("Mermaid");return o(),l("div",null,[e[2]||(e[2]=d('<h1 id="虚拟文件系统" tabindex="-1">虚拟文件系统 <a class="header-anchor" href="#虚拟文件系统" aria-label="Permalink to &quot;虚拟文件系统&quot;">​</a></h1><div class="epigraph"><p>VFS 给出 inode、目录、超级块的一套操作表；具体文件系统只填这些操作。</p><footer>—— 据 Kleiman, Vnodes: An Architecture for Multiple File System Types in Sun UNIX, 1986；Linux VFS 文档的整理</footer></div><p><a href="/cs/hard-symlink">上一课</a>把块请求送进一种设备。<a href="/cs/file-bytestream">文件作为字节流</a>与 <a href="/cs/inode-dir">inode</a> 却可能落在 ext4、NFS、tmpfs、proc 上。若 <code>read</code> 里写满每种 FS 的分支，内核无法扩展。缺口是<strong>虚拟文件系统</strong>：公共对象与函数指针，底下才是真正布局。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户只看见路径与描述符。内核需要：挂载点把某设备上的树接到目录树上；跨 FS 的 <code>rename</code> 有的能做有的不能；管道没有超级块。缺口不是再发明字节流，而是 vnode/inode 的操作向量：<code>lookup</code>、<code>create</code>、<code>readpage</code>、<code>write_inode</code>。proc 与套接字也可以提供「文件」操作而不含磁盘块。</p><p>本课不把每种 FS 的磁盘格式写成附录。</p><p><span class="marginnote">超级块描述已挂载实例；dentry 缓存名字查找；inode 仍是对象。VFS 缓存与页 Cache 合作：lookup 命中则不读目录块。</span></p><p><span class="marginnote">直觉类比：VFS 像一组统一的「插座标准」，ext4、NFS、tmpfs 是各家电器——只要实现同一排插脚（lookup、readpage、write_inode 这些函数指针），用户态的插头（系统调用）不用改一根线就能用。换文件系统换的是电器，不是墙上的插座。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>open</code> 在 VFS：沿 dentry 走，到挂载点切换超级块，调用该 FS 的 <code>lookup</code>。<code>read</code> 调文件操作，可能进入页 Cache，再调 <code>readpage</code> 让具体 FS 填页。NFS 的 <code>readpage</code> 走网络而不是<a href="/cs/disk-sched">磁盘调度</a>；tmpfs 的页就是匿名内存。对用户，系统调用号不变。</p>',10)),(o(),r(s,null,{default:a(()=>[E(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22open%2Fread%22%5D%20--%3E%20VFS%5B%22VFS%20%E6%93%8D%E4%BD%9C%E8%A1%A8%22%5D%0A%20%20VFS%20--%3E%20EXT%5B%22%E7%A3%81%E7%9B%98%20FS%22%5D%0A%20%20VFS%20--%3E%20NFS%5B%22%E7%BD%91%E7%BB%9C%20FS%22%5D%0A%20%20VFS%20--%3E%20MEM%5B%22%E5%86%85%E5%AD%98%20FS%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>VFS 让「一切皆文件」可实现：设备节点、管道、后来的套接字都挂同一描述符表，操作不同。挂载把多棵树合成用户看见的一棵，路径解析仍是目录课的算法，只是跨超级块。脏 inode 的回写经 VFS 调具体 <code>write_inode</code>，缓冲课的脏集在这一层分流。</p><p>与数据库栏无关：这里没有关系代数。不要把 VFS 写成查询计划。</p><p><span class="marginnote">数字实例：<code>open(&quot;/mnt/nfs/a.txt&quot;)</code> 的路径解析若 dentry 缓存全冷，VFS 要逐级调 <code>lookup</code>——<code>a.txt</code> 这一级落在 NFS 超级块上，一次 <code>lookup</code> 就是一次网络往返（毫秒级）；同一文件在 ext4 上则是一次（或零次，若缓存命中）磁盘元数据读（百微秒级）。同一个 VFS 调用，后端成本差了三个量级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 FUSE 的全部用户态协议，不把命名空间与绑定挂载的容器语义写完。也不保证所有 FS 支持同一套扩展属性。下一课要问：具体设备如何把块搬进内存——可编程 I/O 与 DMA。</p><p>文件锁（<code>flock</code>/<code>fcntl</code>）也走 VFS，具体 FS 可以忽略或实现；本课不把强制锁当默认。</p><p>后课默认：文件操作经 VFS 分发。字节如何从控制器进帧，下一课 I/O 与 DMA。</p>',8)),(o(),r(s,null,{default:a(()=>[E(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPEN%5B%22open%20%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20WALK%5B%22%E6%B2%BF%20dentry%20%E9%80%90%E7%BA%A7%E8%A7%A3%E6%9E%90%22%5D%0A%20%20WALK%20--%3E%20MNT%7B%22%E5%BD%93%E5%89%8D%E7%BA%A7%E6%98%AF%E6%8C%82%E8%BD%BD%E7%82%B9%3F%22%7D%0A%20%20MNT%20--%20%22%E6%98%AF%22%20--%3E%20SWITCH%5B%22%E5%88%87%E6%8D%A2%E5%88%B0%E6%96%B0%E8%B6%85%E7%BA%A7%E5%9D%97%22%5D%0A%20%20MNT%20--%20%22%E5%90%A6%22%20--%3E%20LK%5B%22%E8%B0%83%E6%9C%AC%E7%BA%A7%20FS%20%E7%9A%84%20lookup%22%5D%0A%20%20SWITCH%20--%3E%20LK%0A%20%20LK%20--%3E%20HIT%7B%22dentry%20%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20HIT%20--%20%22%E6%98%AF%22%20--%3E%20DONE%5B%22%E7%9B%B4%E6%8E%A5%E8%BF%94%E5%9B%9E%20inode%22%5D%0A%20%20HIT%20--%20%22%E5%90%A6%22%20--%3E%20REAL%5B%22%E5%90%8E%E7%AB%AF%E5%AE%9E%E4%BD%9C%3A%20%E7%A3%81%E7%9B%98%E5%9D%97%20%2F%20%E7%BD%91%E7%BB%9C%E5%BE%80%E8%BF%94%20%2F%20%E5%8C%BF%E5%90%8D%E9%A1%B5%22%5D%0A%20%20REAL%20--%3E%20DONE%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p><span class="marginnote">常见误区：初学者容易以为读一个文件只会碰到一种文件系统，实际上路径每一级都可能跨挂载点换超级块——<code>/usr</code> 在根盘、<code>/home</code> 在另一块盘、<code>/proc</code> 压根没有磁盘；VFS 的活就是在这些边界上平滑切换，让调用方完全无感。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VFS 用操作表统一 inode 与文件；磁盘只是后端一种。</li><li>挂载拼接目录树；页 Cache 仍在 VFS 之下被调用。</li><li>设备搬字节的方式是 DMA 课的缺口。</li><li>出处：Kleiman, 1986；Tanenbaum <em>MOS</em>；Linux VFS 概述（作为实现对照）。</li></ul>',3))])}const u=c(p,[["render",A]]);export{h as __pageData,u as default};
